CREATE TABLE public.petty_cash_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),branch_id text NOT NULL REFERENCES public.branches(id),kind text NOT NULL CHECK(kind IN('Top-up','Expense')),amount numeric(16,2) NOT NULL CHECK(amount>0 AND amount::text NOT IN('NaN','Infinity','-Infinity')),category text NOT NULL,description text NOT NULL,reference text NOT NULL DEFAULT '',date date NOT NULL DEFAULT (now() AT TIME ZONE 'Asia/Colombo')::date,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.petty_cash_entries TO authenticated; GRANT ALL ON public.petty_cash_entries TO service_role;
ALTER TABLE public.petty_cash_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY petty_cash_read ON public.petty_cash_entries FOR SELECT TO authenticated USING(public.staff_can('Manage expenses',branch_id));
CREATE INDEX petty_cash_branch ON public.petty_cash_entries(branch_id,date);
CREATE FUNCTION public.record_petty_cash(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b text:=p->>'branch_id';k text:=p->>'kind';a numeric:=round((p->>'amount')::numeric,2);bal numeric;eid uuid; BEGIN IF NOT public.staff_can('Manage expenses',b) THEN RAISE EXCEPTION 'Expense management permission required'; END IF; IF k NOT IN('Top-up','Expense') OR a IS NULL OR a<=0 OR a::text IN('NaN','Infinity','-Infinity') OR nullif(trim(p->>'description'),'') IS NULL THEN RAISE EXCEPTION 'Enter a valid amount and description'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('petty-cash-'||b,0)); SELECT coalesce(sum(CASE WHEN kind='Top-up' THEN amount ELSE -amount END),0) INTO bal FROM public.petty_cash_entries WHERE branch_id=b; IF k='Expense' AND a>bal THEN RAISE EXCEPTION 'Expense exceeds available petty cash'; END IF; INSERT INTO public.petty_cash_entries(branch_id,kind,amount,category,description,reference,created_by) VALUES(b,k,a,coalesce(nullif(trim(p->>'category'),''),'Other'),trim(p->>'description'),coalesce(p->>'reference',''),auth.uid()) RETURNING id INTO eid; INSERT INTO public.audit_events(actor_id,actor_name,branch_id,category,action,description,record_id) VALUES(auth.uid(),coalesce((SELECT display_name FROM public.profiles WHERE id=auth.uid()),'Staff'),b,'Petty cash',CASE WHEN k='Top-up' THEN 'Funded' ELSE 'Spent' END,CASE WHEN k='Top-up' THEN 'Added LKR ' ELSE 'Spent LKR ' END||to_char(a,'FM999,999,999,999,990.00')||' — '||trim(p->>'description'),eid::text); RETURN eid; END $$;
REVOKE ALL ON FUNCTION public.record_petty_cash(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_petty_cash(jsonb) TO authenticated;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.save_staff_role(jsonb)'::regprocedure) INTO d; d:=replace(d,'''Transfer stock'']::text[]','''Transfer stock'',''Manage expenses'']::text[]'); EXECUTE d; END $$;